#!/usr/bin/env python
"""
Generate signing secrets for local or deployed environments.

Usage:
    uv run python scripts/generate_secrets.py
    uv run python scripts/generate_secrets.py --write .env
"""

from __future__ import annotations

import argparse
import secrets
from pathlib import Path

_SECRET_BYTES = 48


def _token() -> str:
    return secrets.token_urlsafe(_SECRET_BYTES)


def _format_block() -> str:
    jwt_secret = _token()
    otp_secret = _token()
    api_token = _token()
    job_token = _token()
    return (
        "# Signing secrets — generated by scripts/generate_secrets.py\n"
        f'JWT_SECRET_KEY="{jwt_secret}"\n'
        f'OTP_HMAC_SECRET="{otp_secret}"\n'
        f'API_AUTHORIZATION_TOKEN="{api_token}"\n'
        f'INTERNAL_JOB_TOKEN="{job_token}"\n'
    )


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Generate JWT, OTP HMAC, API authorization, and internal job tokens."
    )
    parser.add_argument(
        "--write",
        metavar="ENV_FILE",
        help="Append generated secrets to the given env file (default: print to stdout).",
    )
    args = parser.parse_args()

    block = _format_block()
    if args.write:
        env_path = Path(args.write)
        needs_leading_newline = env_path.exists() and env_path.stat().st_size > 0
        with env_path.open("a", encoding="utf-8") as handle:
            if needs_leading_newline:
                handle.write("\n")
            handle.write(block)
        print(f"Appended secrets to {env_path}")
        return 0

    print(block, end="")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())